function precedentsSection(){
  return `<section id="precedents" class="precedents-section" aria-labelledby="precedents-title">
    <div class="section-heading">
      <h2 id="precedents-title">${tr('Built Precedents & Spatial Case Studies','Izvedeni antologijski primeri i prostorne studije')}</h2>
      <span class="tag">${PRECEDENTS.length} ${tr('case studies','studija slučaja')}</span>
    </div>
    <p class="lede">${tr('Real built architecture where universal access generates spatial identity rather than an afterthought. Measured parameters, verified acoustic/lighting data, and core design lessons.','Realizovana arhitektura gde pristupačnost generiše prostorni identitet umesto naknadnog prilagođavanja. Izmereni parametri, provereni podaci akustike/osvetljenja i ključne lekcije.')}</p>
    <div class="precedent-grid">
      ${PRECEDENTS.map(p => `
        <article class="precedent-card" id="precedent-${esc(p.id)}">
          <div class="precedent-head">
            <div class="precedent-meta">
              <span class="meta-label">${esc(tx(p.category))}</span>
              <span class="tag">${esc(p.year)}</span>
            </div>
            <h3>${esc(tx(p.title))}</h3>
            <p class="precedent-sub">${esc(p.architect)} · ${esc(p.location)}</p>
          </div>
          <p class="precedent-hero"><strong>${tr('Key spatial idea','Ključna prostorna ideja')}:</strong> ${esc(tx(p.hero))}</p>
          <div class="precedent-measured">
            <h4>${tr('Measured architectural evidence','Izmereni arhitektonski parametri')}</h4>
            <ul>
              ${p.measured.map(m => `<li>${esc(tx(m))}</li>`).join('')}
            </ul>
          </div>
          <blockquote class="precedent-lesson">
            <p><strong>${tr('Studio lesson','Pouka za studio')}:</strong> ${esc(tx(p.lesson))}</p>
          </blockquote>
        </article>
      `).join('')}
    </div>
  </section>`;
}

function brief(){
  const briefNav = [
    ['place', tr('01 / The place', '01 / Mesto')],
    ['learn', tr('02 / What you learn', '02 / Šta učimo')],
    ['principles', tr('03 / Seven principles', '03 / Sedam principa')],
    ['standards', tr('04 / Spatial standards', '04 / Standardi i propisi')],
    ['neuro-sensory', tr('05 / Sensory & neurodivergent', '05 / Čula i neurodivergentnost')],
    ['evidence', tr('06 / What you make', '06 / Šta pravimo')],
    ['review', tr('07 / How we review', '07 / Kako razmatramo')],
    ['ai', tr('08 / Working with AI', '08 / Rad sa AI')],
    ['site', tr('09 / Site facts', '09 / Podaci lokacije')],
    ['themes', tr('10 / Project themes', '10 / Teme projekta')],
    ['hand-in', tr('11 / Hand-in items', '11 / Sadržaj predaje')],
    ['marks', tr('12 / Marking scheme', '12 / Ocenjivanje')]
  ];
  return `<div class="page-top"><div><p class="eyebrow">${tr('Project brief / Proposal','Projektni zadatak / Predlog')}</p><h1>${tr('An everyday place.<br>A shared possibility.','Svakodnevno mesto.<br>Zajednička mogućnost.')}</h1><p class="lede">${tr('Redesign one everyday place with the people who use it. Make access, choice and belonging visible in architectural decisions.','Preprojektujte jedno svakodnevno mesto sa ljudima koji ga koriste. Pokažite pristup, izbor i pripadanje kroz arhitektonske odluke.')}</p></div>${pageMeta()}</div><div class="document"><nav class="document-index" aria-label="${tr('Brief sections','Delovi zadatka')}">${briefNav.map(([id,label])=>link('#'+id,label)).join('')}</nav><div>
  <section id="place"><h2>${tr('Begin with a real situation.','Počnite od stvarne situacije.')}</h2><p>${tr('A neighbourhood entrance, shared courtyard, small public interior or route to a service: choose a manageable place together. The site and association have not yet been selected.','Ulaz u komšiluku, zajedničko dvorište, mali javni enterijer ili put do usluge: zajedno izaberite mesto primerenog obima. Lokacija i udruženje još nisu izabrani.')}</p><p>${tr('Work at three connected scales: the journey to the place, the organisation of the place, and one detail that changes its use. A ramp alone is not the whole experience.','Radite u tri povezane razmere: put do mesta, organizacija mesta i jedan detalj koji menja način korišćenja. Rampa sama nije celo iskustvo.')}</p><div class="notice"><p>${tr('This is a proposed studio framework for third-year architecture students. Teaching hours, credits, assessment weights and formal accommodations must be set by the responsible course team. This site does not award credits.','Ovo je predloženi okvir studija za treću godinu arhitekture. Fond časova, bodove, ponderisanje ocena i formalna prilagođavanja određuje odgovorni nastavni tim. Ovaj sajt ne dodeljuje bodove.')}</p></div></section>
  <section id="learn"><h2>${tr('What you should be able to do.','Po završetku treba da možete:')}</h2><ol><li>${tr('Document an actual spatial barrier without reducing a person to a diagnosis.','da dokumentujete stvarnu prostornu barijeru bez svođenja osobe na dijagnozu;')}</li><li>${tr('Negotiate a brief with coauthors and show where their decisions changed it.','da dogovorite zadatak sa koautorima i pokažete gde su njihove odluke promenile projekat;')}</li><li>${tr('Compare spatial alternatives using access, choice, sensory comfort and effort.','da uporedite prostorne varijante prema pristupu, izboru, čulnoj udobnosti i naporu;')}</li><li>${tr('Test a critical detail at full scale and revise it from evidence.','da ispitate ključni detalj u punoj veličini i doradite ga prema nalazima;')}</li><li>${tr('Communicate a coherent architectural proposal through coordinated spatial representations and a companion plain-language explanation.','da saopštite celovit arhitektonski predlog usklađenim prostornim prikazima i pratećim objašnjenjem na jednostavnom jeziku;')}</li><li>${tr('If you use AI, identify its contribution, failures and your independent checks. Otherwise document your own checking method.','da, ako koristite AI, prepoznate njegov doprinos i greške i zabeležite sopstvene nezavisne provere; u suprotnom, da dokumentujete svoj postupak provere.')}</li></ol></section>
  ${principlesDetailSection()}
  ${spatialStandardsSection()}
  ${neuroSensorySection()}
  <section id="evidence"><h2>${tr('One connected project record.','Jedan povezan zapis projekta.')}</h2><p>${tr('Carry the same place and the same questions through the six stages. Each hand-in builds on the previous one. Use the scales that make your evidence legible; the course team must confirm formal drawing requirements.','Isto mesto i ista pitanja prolaze kroz šest faza. Svaki novi A3 i deo projekta nastavljaju prethodni rad. Koristite razmere koje čine dokaz čitljivim; nastavni tim potvrđuje formalne zahteve za crteže.')}</p>${stages.map(s=>`<a class="stage-row" href="studio.html?stage=${s.id}"><span class="num">${number(s.id)}</span><div><strong>${esc(tx(s.title))}</strong><small>${esc(tx(s.deliverables)[0])}</small></div>${arrow}</a>`).join('')}</section>
  <section id="review"><h2>${tr('A review that changes the project.','Razmatranje koje menja projekat.')}</h2><p>${tr('The following is a proposed feedback rubric, not an approved grading scheme. Use “evidence present”, “needs revision” and “not yet tested” for each dimension. A negative finding is useful if the response is documented.','Sledi predlog rubrike za povratnu informaciju, ne odobrena šema ocenjivanja. Za svaku dimenziju koristite: „dokaz postoji”, „potrebna dorada” i „još nije ispitano”. Negativan nalaz je koristan ako je odgovor dokumentovan.')}</p><div class="principles">${[
 [tr('Spatial evidence','Prostorni dokazi'),tr('Measured conditions, a complete journey and uncertainty clearly marked.','Izmereni uslovi, celovito kretanje i jasno označene neizvesnosti.')],
 [tr('Shared decisions','Zajedničke odluke'),tr('Coauthors’ priorities, disagreements and changes are traceable without exposing personal information.','Prioriteti koautora, neslaganja i promene su sledljivi bez otkrivanja ličnih podataka.')],
 [tr('Architectural resolution','Arhitektonska razrada'),tr('Plans, sections and critical details agree with one another and with the proposed experience.','Osnove, preseci i ključni detalji međusobno su usklađeni i podržavaju zamišljeno korišćenje.')],
 [tr('Testing and revision','Ispitivanje i dorada'),tr('An actual test, its limitations and a before/after decision are shown.','Prikazani su stvarno ispitivanje, njegove granice, početna odluka i izmena doneta posle provere.')],
 [tr('Accessible communication','Pristupačno saopštavanje'),tr('Meaning survives beyond the drawing: descriptions, readable structure and a usable format.','Smisao postoji i izvan crteža: opisi, čitljiva struktura i upotrebljiv format.')]
 ].map(([h,p])=>`<article><div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div></section>
  <section id="ai"><h2>${tr('AI can assist. It cannot consent.','AI može da pomogne. Ne može da da saglasnost.')}</h2><p>${tr('Use AI to generate alternatives, organise non-sensitive notes or draft a description. Verify every spatial claim against measurements and an applicable source. An invented persona cannot speak for a coauthor; a generated image cannot prove accessibility.','Koristite AI za varijante, organizaciju neosetljivih beležaka ili nacrt opisa. Svaku prostornu tvrdnju proverite merenjem i odgovarajućim izvorom. Izmišljena persona ne govori umesto koautora; generisana slika ne dokazuje pristupačnost.')}</p><p>${tr('Participation must remain possible without an AI account, a paid tool or image generation.','Učešće mora biti moguće bez AI naloga, plaćenog alata ili generisanja slike.')}</p>${link('resources.html',tr('Explore the reference library','Otvori biblioteku izvora')+arrow,'button secondary')}</section>${siteFacts()}</div></div>`;
}

function fieldMaterial(){return `<section id="field-material" class="field-material" aria-labelledby="field-title"><div class="section-heading"><h2 id="field-title">${tr('From the field archive: Živimo zajedno','Iz terenske zbirke: Živimo zajedno')}</h2><span class="tag">${tr('Teaching material / Source under review','Nastavni materijal / Izvor u proveri')}</span></div><div class="field-grid"><figure><a href="assets/fieldwork/zivimo-zajedno-sketch.jpg"><img src="assets/fieldwork/zivimo-zajedno-sketch.jpg" width="1000" height="563" loading="lazy" decoding="async" alt="${tr('Blue-ink site sketch: two larger rectangular areas separated by a narrow strip with steps; see the structured description alongside.','Terenska skica plavom olovkom: dve veće pravougaone površine razdvaja uska traka sa stepenicama; strukturisani opis je pored.')}"></a><figcaption>${tr('Unaltered image from the course archive. Open the full-size image. Author, capture date, units and survey accuracy are unconfirmed.','Neizmenjena slika iz nastavne zbirke. Otvori sliku u punoj veličini. Autor, datum snimanja, jedinice i tačnost snimka nisu potvrđeni.')}</figcaption></figure><div><h3>${tr('What can this sketch actually tell us?','Šta ova skica zaista može da nam kaže?')}</h3><p>${tr('A large outline is on the left, a more articulated outline on the right. Between them, a narrow vertical strip meets a flight of steps at the top. Several circular marks and handwritten dimensions appear on the right. North, scale, units and the meaning of the circles are not established.','Levo je veliki obris, desno razuđeniji. Između je uska uspravna traka koja na vrhu dolazi do stepeništa. Desno su kružne oznake i rukom upisane mere. Sever, razmera, jedinice i značenje krugova nisu utvrđeni.')}</p><ol><li>${tr('Redraw only the relationships you can defend; label uncertain readings.','Precrtaj samo odnose koje možeš da potkrepiš; označi neizvesna čitanja.')}</li><li>${tr('Make three lists: observed, measured, still to verify. Do not turn a guess into a dimension.','Napravi tri liste: opaženo, izmereno, tek proveriti. Ne pretvaraj pretpostavku u meru.')}</li><li>${tr('Explain an arrival route in words; identify what another site visit must resolve.','Objasni put dolaska rečima; utvrdi šta sledeća poseta treba da razreši.')}</li></ol><p class="small">${tr('The sketch is a prompt for inquiry, not a verified plan or a claim that this is the agreed site. A phone vibration cannot replace a tactile drawing.','Skica je podsticaj za istraživanje, ne proveren plan niti potvrda dogovorene lokacije. Vibracija telefona ne može zameniti taktilni crtež.')}</p><div class="actions"><a class="button secondary" href="docs/route-evidence.txt" download>${tr('Download the route worksheet','Preuzmi list za istraživanje putanje')}</a><a class="mini-link" href="studio.html?stage=1">${tr('Use in stage 01','Primeni u fazi 01')} ↗</a></div></div></div><p class="help">${tr('Source: teaching material supplied by the course lead, reviewed 1 October 2026. This source image is excluded from the general content licence; further reuse needs its own rights check.','Izvor: nastavni materijal koji je dostavio voditelj predmeta, pregledan 1. oktobra 2026. Ova izvorna slika nije obuhvaćena opštom licencom sadržaja; dalja upotreba traži posebnu proveru prava.')}</p></section><section aria-labelledby="exercise-title"><div class="section-heading"><h2 id="exercise-title">${tr('Four ways to investigate a place','Četiri načina da istražimo mesto')}</h2></div><div class="exercise-grid">${[
 ['A conversation has geometry.','Razgovor ima geometriju.','Trace sightlines, backlighting and distance in a shared room. Discuss with Deaf coauthors which spatial choices help conversation. Draw a revised plan and section.','Prati vidne linije, svetlo iza sagovornika i rastojanja u zajedničkoj prostoriji. Sa gluvim koautorima razmotri prostorne odluke koje pomažu razgovoru. Nacrtaj izmenjenu osnovu i presek.','Gallaudet / DeafSpace','https://gallaudet.edu/campus-design-facilities/campus-design-and-planning/deafspace/',3,'One person does not represent every Deaf person.','Jedna osoba ne predstavlja sve gluve osobe.'],
 ['One destination, different routes.','Jedan cilj, različite putanje.','Compare two routes using width, slope, surfaces, crossings, rest and sensory conditions. Keep units, method and unknowns. Let coauthors choose which trade-offs matter.','Uporedi dve putanje prema širini, nagibu, podlogama, prelazima, odmoru i čulnim uslovima. Sačuvaj jedinice, metod i nepoznato. Koautori biraju koji kompromisi su važni.','UW / AccessMap','https://tcat.cs.washington.edu/accessmap/',1,'An example route is not verified navigation or a universal access score.','Primer putanje nije proverena navigacija niti univerzalna ocena pristupačnosti.'],
 ['A map to explore by touch.','Mapa za istraživanje dodirom.','Build a small relief map from cardboard or a 3D print. With blind or low-vision coauthors, test landmarks and route explanation, then revise confusing symbols and table placement.','Napravi malu reljefnu mapu od kartona ili 3D štampe. Sa slepim ili slabovidim koautorima proveri orijentire i objašnjenje putanje, pa popravi nejasne simbole i položaj na stolu.','TactIcons / CHI 2023','https://arxiv.org/html/2407.20674v1',4,'A blindfold exercise is not a substitute for coauthor knowledge.','Vežba sa povezom ne zamenjuje znanje koautora.'],
 ['A clip that carries its evidence.','Snimak koji prenosi svoj dokaz.','Choose an approved short clip of one architectural interaction. Add checked captions, a description of essential visual information and a transcript. Ask whether each format supports the same design question.','Izaberi odobren kratak snimak jedne arhitektonske interakcije. Dodaj proverene titlove, opis bitnih vizuelnih informacija i transkript. Proveri da li svaki format podržava isto projektantsko pitanje.','W3C / Accessible media','https://www.w3.org/WAI/media/av/',6,'No unreviewed recordings or automatic captions treated as finished work.','Bez nepregledanih snimaka i automatskih titlova predstavljenih kao završen rad.']
 ].map(([en,sr,bodyEn,bodySr,source,url,stage,limitEn,limitSr])=>`<article class="exercise"><span class="meta-label">${tr('Stage','Faza')} ${number(stage)}</span><h3>${tr(en,sr)}</h3><p>${tr(bodyEn,bodySr)}</p><p class="help">${tr(limitEn,limitSr)}</p><a href="${url}">${source} ↗</a><a class="mini-link" href="studio.html?stage=${stage}">${tr('Open the working stage','Otvori radnu fazu')} ↗</a></article>`).join('')}</div><p class="help">${tr('These are teaching proposals derived from the linked sources, not completed student projects or proven learning effects.','Ovo su nastavni predlozi izvedeni iz povezanih izvora, ne završeni studentski radovi niti dokazani efekti učenja.')}</p></section>`;}

function library(){
  return `<div class="page-top"><div><p class="eyebrow">${tr('Reference library / Read → apply → question','Biblioteka / Pročitaj → primeni → preispitaj')}</p><h1>${tr('Ideas to work with.','Ideje za rad.')}</h1><p class="lede">${tr('A focused reading shelf for the studio. Each source has a practical job in the project.','Odabrana literatura za studio. Svaki izvor ima konkretnu ulogu u projektu.')}</p></div><span class="tag">${tr('Sources, not a substitute for fieldwork','Izvori ne zamenjuju teren')}</span></div>
  <div class="actions">
    <a class="button secondary" href="#visual-atlas">${tr('Visual atlas (5 details)','Vizuelni atlas (5 detalja)')} ↓</a>
    <a class="button secondary" href="#precedents">${tr('Built precedents (6 studies)','Izvedeni primeri (6 studija)')} ↓</a>
    <a class="button secondary" href="#field-material">${tr('Explore Živimo zajedno material','Istraži materijal Živimo zajedno')} ↓</a>
    <a class="button secondary" href="#exercise-title">${tr('Four studio exercises','Četiri studijske vežbe')} ↓</a>
  </div>
  <div class="filter-bar"><div><label for="resource-search">${tr('Search the library','Pretraži biblioteku')}</label><input id="resource-search" type="search" placeholder="${tr('A topic, source or method…','Tema, izvor ili metoda…')}"></div><div><label for="resource-stage">${tr('Project stage','Faza projekta')}</label><select id="resource-stage"><option value="all">${tr('All stages','Sve faze')}</option>${stages.map(s=>`<option value="${s.id}">${number(s.id)} — ${esc(tx(s.title))}</option>`).join('')}</select></div></div><p id="resource-count" class="small muted" role="status"></p><div id="resource-results" class="resource-list"></div>
  ${visualAtlasSection()}
  ${precedentsSection()}
  ${fieldMaterial()}`;
}
function ethics(){return `<div class="page-top"><div><p class="eyebrow">${tr('Working agreement / Proposed','Dogovor o radu / Predlog')}</p><h1>${tr('With people.<br>With responsibility.','Sa ljudima.<br>Sa odgovornošću.')}</h1><p class="lede">${tr('Coauthors have a say in the question, the process and what becomes public.','Koautori odlučuju o pitanju, procesu i tome šta postaje javno.')}</p></div></div><div class="readable"><div class="principles">${[
 [tr('Agree the terms before the first visit.','Dogovorite uslove pre prve posete.'),tr('Ask about preferred communication, accessible meeting options, timing, breaks and whether a support person is welcome. Participation is voluntary; no diagnosis is required for a contribution.','Pitajte za način komunikacije, pristupačne mogućnosti susreta, termine, pauze i prisustvo osobe podrške. Učešće je dobrovoljno; dijagnoza nije potrebna za prilog.')],
 [tr('Leave room to disagree.','Ostavite prostor za neslaganje.'),tr('A coauthor can reject a premise, ask for another format, stop a test or decline publication. Record disagreement respectfully; do not turn it into a student failure or an endorsement.','Koautor može da odbaci pretpostavku, zatraži drugi format, prekine ispitivanje ili odbije objavu. Zabeležite neslaganje sa poštovanjem; ne pretvarajte ga u studentski neuspeh ili saglasnost.')],
 [tr('Publish only what was agreed.','Objavite samo dogovoreno.'),tr('The GitHub pinboard is public. Do not share names, faces, diagnoses, precise home locations or private interview recordings without specific permission. Prefer anonymised spatial observations.','GitHub tabla je javna. Ne delite imena, lica, dijagnoze, tačne kućne adrese ili privatne snimke razgovora bez konkretne dozvole. Birajte anonimizovana prostorna zapažanja.')],
 [tr('Recognise work, not just participation.','Priznajte rad, ne samo prisustvo.'),tr('Agree attribution, expenses and any compensation before asking for time. There is no confirmed compensation budget for this course yet. A public credit is not payment.','Pre angažovanja dogovorite priznanje autorstva, troškove i naknadu. Budžet naknada za ovaj predmet još nije potvrđen. Javno navođenje imena nije honorar.')],
 [tr('Make formats equivalent.','Učinite formate ravnopravnim.'),tr('An idea or feedback can be shared through text or a sketch. Assessed architectural work is reviewed on the weekly A3 and signed on paper; it must communicate scale, levels, dimensions and spatial relationships in an agreed accessible format.','Ideja ili komentar mogu se preneti tekstom ili skicom. Arhitektonski rad koji se vrednuje pregleda se na nedeljnom A3 listu i potpisuje na papiru; mora da pokaže razmeru, kote, mere i prostorne odnose u dogovorenom pristupačnom formatu.')],
 [tr('Return the work and its limits.','Vratite rad i njegova ograničenja.'),tr('Let coauthors review the final record before publication. Agree where the archive lives and how corrections are requested. Public copies and Git history may persist after an item is removed; never promise complete erasure.','Koautori pregledaju završni zapis pre objave. Dogovorite gde se čuva i kako se traže ispravke. Javne kopije i Git istorija mogu ostati i posle uklanjanja priloga; ne obećavajte potpuno brisanje.')]
 ].map(([h,p])=>`<article><div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div><div class="notice"><p>${tr('No disability simulations. Learn from real environments, direct dialogue and tests that partners have chosen to take part in.','Bez simulacija invaliditeta. Učimo iz stvarnih okruženja, neposrednog razgovora i provera za koje su se partneri odlučili.')}</p></div></div>`;}
function comfortTools(){return `<section class="comfort-tools" aria-labelledby="comfort-title"><h2 id="comfort-title">${tr('Make room for your way of reading.','Napravi prostor za svoj način čitanja.')}</h2><p>${tr('These settings change the presentation, not the content. Your browser zoom, screen reader and operating-system settings still work.','Ova podešavanja menjaju prikaz, ne sadržaj. Uvećavanje pregledača, čitač ekrana i podešavanja operativnog sistema i dalje rade.')}</p><div class="actions"><button id="access-large" aria-pressed="${document.documentElement.classList.contains('large-text')}">${tr('Larger text','Veći tekst')}</button><button id="access-contrast" aria-pressed="${document.documentElement.classList.contains('strong-contrast')}">${tr('Stronger contrast','Jači kontrast')}</button></div><p id="comfort-status" class="help" role="status">${tr('Preferences stay in this browser when storage is allowed.','Podešavanja ostaju u ovom pregledaču kada je čuvanje dozvoljeno.')}</p><details><summary>${tr('Try a short haptic pulse — optional experiment','Probaj kratak haptički impuls — neobavezan ogled')}</summary><div><p>${tr('One short vibration, only when you press the test button. Nothing vibrates automatically. This is an experiment with another feedback channel, not a tactile map or proof of accessibility.','Jedna kratka vibracija, samo kada pritisneš probni taster. Ništa ne vibrira automatski. Ovo je ogled sa drugim kanalom povratne informacije, ne taktilna mapa niti dokaz pristupačnosti.')}</p><p class="help">${tr('Safari and iPhone do not support this web API. Some other browsers expose the API without producing vibration. A visual text response always remains.','Safari i iPhone ne podržavaju ovaj web API. Neki drugi pregledači ga izlažu bez stvarne vibracije. Tekstualni odgovor je uvek dostupan.')}</p><button id="test-haptic">${tr('Test one short pulse','Probaj jedan kratak impuls')}</button><p id="haptic-status" role="status" class="help"></p><p class="small"><a href="https://www.w3.org/TR/vibration/">W3C Vibration API</a> · <a href="https://developer.mozilla.org/en-US/docs/Web/API/Navigator/vibrate">${tr('Browser support','Podrška pregledača')}</a></p></div></details></section>`;}
function accessibility(){return `<div class="page-top"><div><p class="eyebrow">${tr('Access / A continuing practice','Pristup / Stalna praksa')}</p><h1>${tr('Different ways in.','Različiti putevi do sadržaja.')}</h1><p class="lede">${tr('The site should demonstrate the care we ask for in the studio. Here is what it supports, and what still needs work.','Sajt treba da pokaže pažnju koju tražimo u studiju. Ovo podržava; na ovome još treba raditi.')}</p></div></div><div class="readable"><div class="actions"><button id="access-reading">${tr('Toggle simple view','Uključi / isključi jednostavan prikaz')}</button><button id="print-page">${tr('Print this page','Štampaj stranicu')}</button></div>${comfortTools()}<h2>${tr('Use the format that works for you.','Koristi format koji ti odgovara.')}</h2><ul><li>${tr('Keyboard navigation, a skip link, visible focus and native buttons and forms.','Navigacija tastaturom, prečica do sadržaja, vidljiv fokus i standardni tasteri i forme.')}</li><li>${tr('A calendar and an equivalent event list. No event is accessible only through a visual grid.','Kalendar i ravnopravna lista događaja. Nijedan događaj nije dostupan samo preko vizuelne mreže.')}</li><li>${tr('A simple view reduces the number of simultaneous columns. Browser zoom remains available.','Jednostavan prikaz smanjuje broj istovremenih kolona. Uvećavanje u pregledaču ostaje dostupno.')}</li><li>${tr('Text contributions are independent of drawing, colour or pointer precision. Images should have descriptions.','Tekstualni prilozi ne zavise od crtanja, boje ili preciznosti pokazivača. Slike treba da imaju opise.')}</li><li>${tr('English and Serbian interfaces, with the document language updated when you switch. User contributions keep their original language.','Interfejs na engleskom i srpskom, sa promenom jezika dokumenta pri prebacivanju. Prilozi zadržavaju svoj izvorni jezik.')}</li><li>${tr('No autoplay, scrolling effects or required animation. Reduced-motion preferences are respected.','Bez automatske reprodukcije, efekata skrolovanja i obaveznih animacija. Poštuje se podešavanje smanjenog kretanja.')}</li></ul><h2>${tr('Known limits.','Poznata ograničenja.')}</h2><ul><li>${tr('WCAG 2.2 AA is the target, not a claim of certification. Testing with assistive-technology users has not yet taken place.','WCAG 2.2 AA je cilj, ne tvrdnja o sertifikaciji. Provera sa korisnicima asistivnih tehnologija još nije održana.')}</li><li>${tr('Drawing on the optional canvas requires a pointer. A separate text route and file attachments carry the same role.','Crtanje na neobaveznom platnu zahteva pokazivač. Zaseban tekstualni put i prilozi imaju ravnopravnu ulogu.')}</li><li>${tr('Public posting and commenting happen on GitHub and require its account. The studio cannot guarantee GitHub’s accessibility or availability.','Javno objavljivanje i komentarisanje odvijaju se na GitHubu i zahtevaju nalog na toj platformi. Studio ne može da garantuje pristupačnost ni dostupnost GitHuba.')}</li><li>${tr('Draft text stays in browser storage if permitted; selected files and sketches are not saved automatically. Shared computers are not private. Download your work.','Tekst nacrta ostaje u memoriji pregledača ako je dozvoljena; izabrani fajlovi i skice ne čuvaju se automatski. Zajednički računar nije privatan. Preuzmi svoj rad.')}</li><li>${tr('Without JavaScript, the basic project introduction and direct contribution links remain readable. Interactive stages, calendar and draft tools need JavaScript. First load and the live board need a network; this is not an offline application.','Bez JavaScripta ostaju čitljivi osnovni uvod i direktne veze za priloge. Interaktivne faze, kalendar i nacrti zahtevaju JavaScript. Prvo učitavanje i živa tabla zahtevaju mrežu; ovo nije oflajn aplikacija.')}</li></ul><p>${tr('Report a barrier without posting personal information. A dedicated course contact and response time have not yet been agreed.','Prijavi prepreku bez objavljivanja ličnih podataka. Kontakt osoba predmeta i rok odgovora još nisu dogovoreni.')}</p>${link(REPO+'/issues/new?title='+encodeURIComponent('[Accessibility] '),tr('Report an access barrier on GitHub','Prijavi prepreku na GitHubu')+arrow,'button secondary')}<hr><p class="small muted">${tr('Reference:','Izvor:')} <a href="https://www.w3.org/WAI/standards-guidelines/wcag/">W3C Web Content Accessibility Guidelines</a>. ${tr('The interface is one learning object, not proof that the architecture it describes is accessible.','Interfejs je jedan nastavni primer, ne dokaz da je arhitektura koju opisuje pristupačna.')}</p></div>`;}
function storageGuide(){return `<details class="storage-guide"><summary>${tr('Optional public board / GitHub','Neobavezna javna tabla / GitHub')}</summary><div><p><strong>${tr('Course work is not handed in here. The weekly record is the A3 reviewed and signed on paper.','Rad na predmetu se ovde ne predaje. Nedeljni zapis je A3 koji se pregleda i potpisuje na papiru.')}</strong></p><ol class="storage-steps"><li><strong>${tr('Prepare here. No account.','Priprema ovde. Bez naloga.')}</strong><p>${tr('Text is saved in this browser when allowed. Selected files and sketches stay in this tab until you leave or reload. Download what you want to keep.','Tekst se čuva u ovom pregledaču ako je dozvoljeno. Izabrani fajlovi i skice ostaju u ovoj kartici do izlaska ili ponovnog učitavanja. Preuzmi ono što želiš da sačuvaš.')}</p></li><li><strong>${tr('Open GitHub. Sign in there.','Otvori GitHub. Prijavi se tamo.')}</strong><p>${tr('This site has no course account and never asks for your GitHub password. The link opens a form on github.com. Review the text; select the stage again for an optional public project reference.','Ovaj sajt nema nalog predmeta i nikada ne traži GitHub lozinku. Veza otvara obrazac na github.com. Pregledaj tekst; za neobaveznu javnu referencu projekta ponovo izaberi fazu.')}</p></li><li><strong>${tr('Attachments upload immediately on GitHub.','Prilozi se na GitHub šalju odmah.')}</strong><p>${tr('Dropping a file into the GitHub editor uploads it before you submit the issue. Attachments in this public repository are accessible without sign-in. Text becomes a public issue when you submit.','Dodavanje fajla u GitHub editor šalje ga pre objave teme. Prilozi ovog javnog repozitorijuma dostupni su bez prijave. Tekst postaje javna tema kada ga objaviš.')}</p></li></ol><p>${tr('Browser storage is not a private archive or a backup. Other people using the browser and other pages on the same website origin may access it. Nothing syncs to another device automatically.','Čuvanje u pregledaču nije privatna arhiva niti rezervna kopija. Drugi korisnici pregledača i stranice na istom poreklu sajta mogu mu pristupiti. Ništa se automatski ne prenosi na drugi uređaj.')}</p><p>${tr('Students do not need a GitHub account. This optional board is only for material deliberately shared with the public; the site cannot receive private work. Drive is not connected yet.','Studentima nije potreban GitHub nalog. Ova neobavezna tabla služi samo materijalu koji se svesno deli sa javnošću; sajt ne prima privatne radove. Drive još nije povezan.')}</p><p class="small"><a href="https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/attaching-files">${tr('GitHub attachment rules','GitHub pravila za priloge')}</a> · <a href="docs/storage.md">${tr('Storage and archive plan (English)','Plan čuvanja i arhive (engleski)')}</a></p></div></details>`;}
function participate(){const draft=draftMemory;return `<div class="page-top"><div><p class="eyebrow">${tr('Optional public board / Ideas and observations','Neobavezna javna tabla / Ideje i zapažanja')}</p><h1>${tr('Put an idea<br>on the table.','Stavi ideju<br>na sto.')}</h1><p class="lede">${tr('Use this only for material you deliberately want to discuss in public. It is not attendance, a course record or a hand-in.','Koristi ovo samo za materijal o kome namerno želiš da razgovaraš javno. Ovo nije evidencija prisustva, evidencija predmeta niti predaja.')}</p></div><span class="tag">${tr('Draft first. Publish by choice.','Prvo nacrt. Objavljuješ po izboru.')}</span></div>${storageGuide()}<div class="contribute-layout"><div><form class="composer" id="contribution-form"><div class="two-col"><div class="field"><label for="contribution-stage">${tr('Project stage','Faza projekta')}</label><select id="contribution-stage">${stages.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${number(s.id)} — ${esc(tx(s.title))}</option>`).join('')}</select></div><div class="field"><label for="contribution-kind">${tr('Contribution','Vrsta priloga')}</label><select id="contribution-kind"><option value="idea" ${draft.kind==='idea'?'selected':''}>${tr('Idea or observation','Ideja ili zapažanje')}</option><option value="submission" ${draft.kind==='submission'?'selected':''}>${tr('Public project reference — not a hand-in','Javna referenca projekta — nije predaja')}</option></select></div></div><div class="field"><label for="contribution-title">${tr('Give it a short title','Daj mu kratak naslov')}</label><input type="text" id="contribution-title" required maxlength="120" value="${esc(draft.title||'')}" placeholder="${tr('For example: a quieter place to wait','Na primer: mirnije mesto za čekanje')}"></div><div class="field"><label for="contribution-text">${tr('What did you notice or propose?','Šta si primetio ili predložio?')}</label><textarea id="contribution-text" required maxlength="6000" rows="7" aria-describedby="text-help">${esc(draft.text||'')}</textarea><p id="text-help" class="help">${tr('Describe the place, the barrier or opportunity, and what you would like to discuss. Text is enough for an idea or feedback. Publishing here does not register an official course submission or a grade.','Opiši mesto, prepreku ili priliku i ono o čemu želiš da razgovaramo. Tekst je dovoljan za ideju ili komentar. Objava ovde ne registruje zvaničnu predaju na predmetu niti ocenu.')}</p></div><details><summary>${tr('Add a file or sketch (optional)','Dodaj fajl ili skicu (neobavezno)')}</summary><div><label for="contribution-file">${tr('Select an image or PDF to prepare','Izaberi sliku ili PDF za pripremu')}</label><input type="file" id="contribution-file" accept="image/png,image/jpeg,application/pdf"><p class="help">${tr('PNG, JPEG or PDF; maximum 10 MB in this preview. Selecting a file here does not upload it. Adding it later in the GitHub editor uploads it immediately.','PNG, JPEG ili PDF; najviše 10 MB u ovom pregledu. Izbor fajla ovde ga ne šalje. Kasnije dodavanje u GitHub editor šalje ga odmah.')}</p><p id="file-status" role="status" class="small"></p><img id="file-preview" class="preview-image" alt="" hidden><label for="image-description">${tr('Describe what the drawing or file communicates','Opiši šta crtež ili fajl saopštava')}</label><textarea id="image-description" rows="3" maxlength="2000">${esc(draft.description||'')}</textarea><h3>${tr('Quick sketch','Brza skica')}</h3><p class="help">${tr('Optional pointer tool. Use the text field above if drawing does not work for you. Download the PNG to keep it.','Neobavezan alat za pokazivač. Koristi tekst iznad ako ti crtanje ne odgovara. Preuzmi PNG da sačuvaš skicu.')}</p><canvas id="sketch" width="1000" height="500" aria-label="${tr('Optional sketch area; text alternative above','Neobavezna površina za skicu; tekstualna alternativa je iznad')}"></canvas><div class="row"><button type="button" id="undo-sketch">${tr('Undo stroke','Vrati potez')}</button><button type="button" id="download-sketch">${tr('Download PNG','Preuzmi PNG')}</button></div></div></details><details class="draft-transfer"><summary>${tr('Move a text draft to another device','Prenesi tekst nacrta na drugi uređaj')}</summary><div><p class="help">${tr('Download a .json copy, then open it here on another device. It includes only the text and stage, never files or sketches. Share the copy through a channel you trust.','Preuzmi .json kopiju, pa je otvori ovde na drugom uređaju. Sadrži samo tekst i fazu, nikada fajlove ili skice. Prenesi kopiju kanalom kome veruješ.')}</p><button type="button" id="export-text-draft">${tr('Download editable copy (.json)','Preuzmi izmenjivu kopiju (.json)')}</button><label for="import-text-draft">${tr('Choose a saved copy','Izaberi sačuvanu kopiju')}</label><input type="file" id="import-text-draft" accept=".json,application/json"><p id="import-status" role="status" class="help"></p><button type="button" id="apply-text-draft" hidden>${tr('Use this text — replace current draft','Upotrebi ovaj tekst — zameni trenutni nacrt')}</button></div></details><p id="draft-status" class="help" role="status">${tr('Only draft text is kept in this browser. Others using this browser can see it. Nothing has been published.','Samo tekst nacrta ostaje u ovom pregledaču. Drugi koji koriste ovaj pregledač mogu da ga vide. Ništa nije objavljeno.')}</p><div class="actions"><button type="button" id="download-draft">${tr('Download text','Preuzmi tekst')}</button><button type="button" id="clear-draft">${recoverDraft?tr('Undo clearing text','Vrati uklonjeni tekst'):tr('Clear saved text','Ukloni sačuvani tekst')}</button><button type="submit" class="button">${tr('Review before sharing','Pregledaj pre deljenja')} ${arrow}</button></div></form><section id="publish-preview" class="composer" hidden style="margin-top:1.3rem" tabindex="-1"><h2>${tr('Ready for a public conversation?','Spremno za javni razgovor?')}</h2><p>${tr('The next link opens an editable GitHub draft. The text becomes a public issue when submitted there. Files added in the GitHub editor upload immediately and are publicly accessible. Sign in on GitHub, not on this site.','Sledeća veza otvara GitHub nacrt koji možeš da izmeniš. Tekst postaje javna tema kada ga tamo objaviš. Fajlovi dodati u GitHub editor šalju se odmah i javno su dostupni. Prijavljuješ se na GitHubu, ne na ovom sajtu.')}</p><div class="notice" id="preview-content"></div><p id="attachment-reminder" class="help"></p><label class="check-line"><input id="public-consent" type="checkbox"><span>${tr('I have removed private information and have permission to share any contributed material.','Uklonio/la sam privatne podatke i imam dozvolu za deljenje priloženog materijala.')}</span></label><div class="actions"><a id="github-draft" class="button" target="_blank" rel="noopener noreferrer" hidden>${tr('Open GitHub draft (new tab)','Otvori GitHub nacrt (nova kartica)')} ${arrow}</a><button type="button" id="back-to-draft">${tr('Keep editing','Nastavi uređivanje')}</button></div></section></div><aside><div class="note-card"><span class="meta-label">${tr('A useful contribution','Koristan prilog')}</span><h3>${tr('Be specific.<br>Leave a question open.','Budi konkretan.<br>Ostavi otvoreno pitanje.')}</h3><p>${tr('“The entrance is difficult” is a start. What happens, where, and under which conditions? What would you like to try?','„Ulaz je težak” je početak. Šta se dešava, gde i u kojim uslovima? Šta želiš da isprobamo?')}</p></div><div class="aside-section"><h3>${tr('Before you post','Pre objave')}</h3><p class="small muted">${tr('No diagnoses, private interview notes, identifiable photos or precise home locations. Agree what can be shared with everyone who contributed.','Bez dijagnoza, privatnih beležaka razgovora, prepoznatljivih fotografija i tačnih kućnih adresa. Dogovori javni sadržaj sa svima koji su doprineli.')}</p>${link('etika.html',tr('Read the working agreement','Pročitaj dogovor o radu')+arrow,'mini-link')}</div><div class="aside-section"><h3>${tr('Prefer a different route?','Više ti odgovara drugi put?')}</h3><p class="small muted">${tr('Download your text if you want to continue elsewhere. This public board is optional and is not a course submission route.','Preuzmi tekst ako želiš da nastaviš rad na drugom mestu. Ova javna tabla je neobavezna i nije put za predaju rada na predmetu.')}</p></div></aside></div><section id="public-board"><div class="section-heading"><h2>${tr('The public pinboard','Javna tabla')}</h2>${link(REPO+'/issues',tr('View on GitHub','Pogledaj na GitHubu')+arrow)}</div><p class="small muted">${tr('Published ideas and public project references from the repository. They are not attendance, course records or hand-ins.','Objavljene ideje i javne reference projekata iz repozitorijuma. One nisu evidencija prisustva, evidencija predmeta niti predaja.')}</p><div class="actions"><button id="load-board">${tr('Load public contributions','Učitaj javne priloge')}</button></div><p id="board-status" role="status" class="small"></p><div id="board-results" class="board-grid"></div></section>`;}

function render(){updateChrome();$('#main').innerHTML=({studio, schedule:calendar, brief, library, ethics, accessibility, participate, subject, work}[view]||studio)();bind();}
function bind(){
  $$('[data-stage]').forEach(b=>b.addEventListener('click',()=>{selected=Number(b.dataset.stage);const url=new URL(location.href);url.searchParams.set('stage',selected);history.replaceState(null,'',url);render();$(`[data-stage="${selected}"]`).focus();announce(tr('Working sheet: ','Radni list: ')+tx(stages[selected-1].title));}));
  $$('[data-role]').forEach(b=>b.addEventListener('click',()=>{role=b.dataset.role;save('role',role);render();$(`[data-role="${role}"]`).focus();announce(tr('Tasks updated for your role.','Zadaci su prilagođeni tvojoj ulozi.'));}));
  $$('[data-check]').forEach(c=>c.addEventListener('change',()=>{const success=save('checks-'+selected,$$('[data-check]:checked').map(c=>Number(c.dataset.check)));announce(success?tr('Checklist saved on this browser.','Lista je sačuvana u ovom pregledaču.'):tr('Browser storage is unavailable. This check will not be kept.','Čuvanje u pregledaču nije dostupno. Ova oznaka neće ostati sačuvana.'));}));
  bindMonth();$('#print-page')?.addEventListener('click',()=>window.print());
  $('#export-calendar')?.addEventListener('click',()=>{try{download('inclusive-studio.ics',createICS(schedule.events,schedule.timezone),'text/calendar;charset=utf-8');announce(tr('Confirmed events downloaded.','Potvrđeni događaji su preuzeti.'));}catch{announce(tr('Calendar export failed. Please use the event list.','Izvoz kalendara nije uspeo. Koristi listu događaja.'));}});
  $('#access-reading')?.addEventListener('click',toggleReading);
  for(const [id,cls,key] of [['access-large','large-text','largeText'],['access-contrast','strong-contrast','contrast']])$('#'+id)?.addEventListener('click',()=>{const enabled=document.documentElement.classList.toggle(cls);$('#'+id).setAttribute('aria-pressed',String(enabled));const kept=save(key,enabled);$('#comfort-status').textContent=kept?tr('Presentation updated and saved in this browser.','Prikaz je promenjen i sačuvan u ovom pregledaču.'):tr('Presentation updated for this page. Browser storage is unavailable.','Prikaz je promenjen za ovu stranicu. Čuvanje nije dostupno.');});
  $('#test-haptic')?.addEventListener('click',()=>{const status=$('#haptic-status');if(typeof navigator.vibrate!=='function'){status.textContent=tr('Vibration is unavailable here. You can use every studio feature without it.','Vibracija ovde nije dostupna. Sve funkcije studija rade i bez nje.');return;}try{const requested=navigator.vibrate(25);status.textContent=requested?tr('One 25 ms pulse requested. Only you can confirm whether you felt it; browser acceptance does not prove vibration.','Zatražen je jedan impuls od 25 ms. Samo ti možeš potvrditi da li si ga osetio/la; prihvatanje u pregledaču ne dokazuje vibraciju.'):tr('The browser declined the pulse. Every studio feature still works.','Pregledač je odbio impuls. Sve funkcije studija i dalje rade.');}catch{status.textContent=tr('Vibration is unavailable. Continue using the text response.','Vibracija nije dostupna. Koristi tekstualni odgovor.');}});
  if(view==='library')bindLibrary();if(view==='participate')bindContributions();
}
function bindMonth(){$$('[data-month]').forEach(b=>b.addEventListener('click',()=>{const direction=b.dataset.month;calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+Number(direction),1);$('#month-grid').innerHTML=monthGrid();bindMonth();$(`[data-month="${direction}"]`).focus();announce($('#month-title').textContent);}));}
function bindLibrary(){const stage=$('#resource-stage');stage.value=new URLSearchParams(location.search).get('stage')||'all';if(!stage.value)stage.value='all';const update=()=>{const query=$('#resource-search').value.toLocaleLowerCase(lang),filtered=resources.filter(r=>(stage.value==='all'||r.stage.includes(Number(stage.value)))&&(r.title+' '+r.organisation+' '+tx(r.why)).toLocaleLowerCase(lang).includes(query));$('#resource-count').textContent=filtered.length+' '+tr('sources','izvora');$('#resource-results').innerHTML=filtered.length?filtered.map(r=>`<article class="resource"><span class="tag">${esc(r.type)}</span><h2>${esc(r.title)}</h2><p class="small">${esc(r.organisation)}</p><p>${esc(tx(r.why))}</p>${link(r.url,tr('Read source','Pročitaj izvor')+arrow)}</article>`).join(''):`<p class="empty">${tr('No matching sources. Try a different term or all stages.','Nema odgovarajućih izvora. Promeni pojam ili izaberi sve faze.')}</p>`;};$('#resource-search').addEventListener('input',update);stage.addEventListener('change',update);update();}
function draftData(){return {stage:Number($('#contribution-stage').value),kind:$('#contribution-kind').value,title:$('#contribution-title').value,text:$('#contribution-text').value,description:$('#image-description').value};}
function markdown(d){return `# ${d.title}\n\nStage ${number(d.stage)} — ${stages[d.stage-1].title.en}\n\n${d.text}\n\n${d.description?'## Drawing / attachment description\n\n'+d.description+'\n\n':''}---\nPrepared in Inclusive Studio.\n`;}
let previewUrl=null,selectedFile=null,sketchStrokes=[],activeStroke=null;
let recoverDraft=null;
function bindContributions(){
  const form=$('#contribution-form');const persist=()=>{selected=Number($('#contribution-stage').value);draftMemory=draftData();if(selectedFile?.type.startsWith('image/')&&!$('#file-preview').hidden)$('#file-preview').alt=draftMemory.description||tr('Selected image; add a description.','Izabrana slika; dodaj opis.');recoverDraft=null;$('#clear-draft').textContent=tr('Clear saved text','Ukloni sačuvani tekst');const address=new URL(location.href);address.searchParams.set('stage',selected);history.replaceState(null,'',address);const ok=save('draft',draftMemory);const message=ok?tr('Text saved in this browser. Files and sketches are not saved automatically. Nothing published.','Tekst je sačuvan u ovom pregledaču. Fajlovi i skice ne čuvaju se automatski. Ništa nije objavljeno.'):tr('Browser storage is unavailable. Download your text before leaving.','Čuvanje u pregledaču nije dostupno. Preuzmi tekst pre izlaska.');if($('#draft-status').textContent!==message)$('#draft-status').textContent=message;$('#publish-preview').hidden=true;$('#public-consent').checked=false;$('#github-draft').hidden=true;};form.addEventListener('input',persist);
  let pendingImport=null,importGeneration=0;
  $('#export-text-draft').addEventListener('click',()=>{download('inclusive-studio-text.json',exportDraft(draftData()),'application/json');announce(tr('Editable text copy downloaded. Files and sketches are not included.','Izmenjiva kopija teksta je preuzeta. Fajlovi i skice nisu uključeni.'));});
  $('#import-text-draft').addEventListener('change',async()=>{const generation=++importGeneration,input=$('#import-text-draft'),file=input.files[0];const current=()=>generation===importGeneration&&input.isConnected&&input.files[0]===file;pendingImport=null;$('#apply-text-draft').hidden=true;if(!file)return;try{if(file.size>100000)throw Error('size');const imported=importDraft(await file.text());if(!current())return;pendingImport=imported;$('#import-status').textContent=tr('Ready to use: ','Spremno za upotrebu: ')+pendingImport.title+' · '+tr('Stage ','Faza ')+pendingImport.stage+'. '+tr('Your current text has not changed. Download it first if needed.','Trenutni tekst nije promenjen. Preuzmi ga prvo ako ti je potreban.');$('#apply-text-draft').hidden=false;}catch{if(!current())return;$('#import-status').textContent=tr('This is not a supported studio text copy. Your current work is unchanged.','Ovo nije podržana tekstualna kopija studija. Trenutni rad nije promenjen.');}});
  $('#apply-text-draft').addEventListener('click',()=>{if(!pendingImport)return;const d=pendingImport;$('#contribution-stage').value=String(d.stage);$('#contribution-kind').value=d.kind;$('#contribution-title').value=d.title;$('#contribution-text').value=d.text;$('#image-description').value=d.description;persist();pendingImport=null;$('#apply-text-draft').hidden=true;$('#import-status').textContent=tr('Text restored. Files and sketches were not imported; existing local attachments remain.','Tekst je vraćen. Fajlovi i skice nisu uvezeni; postojeći lokalni prilozi ostaju.');$('#contribution-title').focus();});
  $('#download-draft').addEventListener('click',()=>{download('studio-stage-'+$('#contribution-stage').value+'.md',markdown(draftData()),'text/markdown;charset=utf-8');announce(tr('Text downloaded.','Tekst je preuzet.'));});
  $('#contribution-file').addEventListener('change',()=>{const file=$('#contribution-file').files[0];selectedFile=file||null;if(previewUrl)URL.revokeObjectURL(previewUrl);$('#file-preview').hidden=true;$('#file-status').textContent='';if(!file)return;if(file.size>10*1024*1024||!['image/png','image/jpeg','application/pdf'].includes(file.type)){$('#file-status').textContent=tr('Choose a PNG, JPEG or PDF no larger than 10 MB.','Izaberi PNG, JPEG ili PDF do 10 MB.');$('#contribution-file').value='';selectedFile=null;return;}$('#file-status').textContent=file.name+' · '+tr('selected locally, not uploaded','izabrano lokalno, nije poslato');if(file.type.startsWith('image/')){previewUrl=URL.createObjectURL(file);$('#file-preview').src=previewUrl;$('#file-preview').alt=$('#image-description').value||tr('Your selected image; add its description below.','Tvoja izabrana slika; dodaj opis ispod.');$('#file-preview').hidden=false;}});
  form.addEventListener('submit',e=>{e.preventDefault();const d=draftData();if(!d.title.trim()||!d.text.trim()){announce(tr('A title and description are required.','Potrebni su naslov i opis.'));return;}if((selectedFile||sketchStrokes.length)&&!d.description.trim()){$('#image-description').closest('details').open=true;$('#image-description').focus();announce(tr('Add a text description for the image or sketch before sharing.','Dodaj tekstualni opis slike ili skice pre deljenja.'));return;}$('#preview-content').replaceChildren();const h=document.createElement('h3'),p=document.createElement('p');h.textContent=d.title;p.textContent=d.text;p.style.whiteSpace='pre-wrap';const meta=document.createElement('p');meta.textContent=tr('Stage ','Faza ')+number(d.stage)+' · '+tx(stages[d.stage-1].title)+' · '+(d.kind==='idea'?tr('Idea','Ideja'):tr('Project work','Projektantski rad'));$('#preview-content').append(meta,h,p);if(d.description){const description=document.createElement('p');description.textContent=d.description;$('#preview-content').append(description);}const handoff=issueDraftLink(d,markdown(d));const longDraft=handoff.longDraft;$('#github-draft').href=handoff.href;$('#public-consent').checked=false;$('#github-draft').hidden=true;$('#attachment-reminder').textContent=tr('Attach approved images or PDFs on GitHub yourself; upload happens immediately there. Download a sketch as PNG first. The local preview does not transfer files. For a public project reference, select the stage in the GitHub form.','Odobrene slike ili PDF samostalno priloži na GitHubu; tamo se šalju odmah. Skicu prvo preuzmi kao PNG. Lokalni pregled ne prenosi fajlove. Za javnu referencu projekta izaberi fazu u GitHub obrascu.');if(longDraft)$('#attachment-reminder').textContent+=tr(' This draft is too long for a link: download your text, then paste it into the GitHub draft.',' Ovaj nacrt je predugačak za vezu: preuzmi tekst, pa ga nalepi u GitHub nacrt.');$('#publish-preview').hidden=false;$('#publish-preview').focus();});
  $('#public-consent').addEventListener('change',e=>{$('#github-draft').hidden=!e.target.checked;});$('#back-to-draft').addEventListener('click',()=>{$('#publish-preview').hidden=true;$('#contribution-text').focus();});
  $('#clear-draft').addEventListener('click',()=>{if(recoverDraft){draftMemory=recoverDraft;save('draft',draftMemory);selected=draftMemory.stage;recoverDraft=null;render();$('#contribution-title').focus();announce(tr('Draft text restored.','Tekst nacrta je vraćen.'));return;}recoverDraft=draftData();['contribution-title','contribution-text','image-description'].forEach(id=>$('#'+id).value='');draftMemory={};save('draft',draftMemory);$('#publish-preview').hidden=true;$('#clear-draft').textContent=tr('Undo clearing text','Vrati uklonjeni tekst');$('#draft-status').textContent=tr('Saved text cleared. Undo is available until you leave this page.','Sačuvani tekst je uklonjen. Možeš ga vratiti dok ne napustiš ovu stranicu.');});
  if(selectedFile){$('#file-status').textContent=selectedFile.name+' · '+tr('selected locally, not uploaded','izabrano lokalno, nije poslato');if(selectedFile.type.startsWith('image/')){if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(selectedFile);$('#file-preview').src=previewUrl;$('#file-preview').alt=$('#image-description').value||tr('Selected image','Izabrana slika');$('#file-preview').hidden=false;}}
  setupSketch();$('#load-board').addEventListener('click',loadBoard);
}
function setupSketch(){const canvas=$('#sketch'),ctx=canvas.getContext('2d');const draw=()=>{ctx.fillStyle='#ffffff';ctx.fillRect(0,0,1000,500);ctx.strokeStyle='#192e27';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';for(const stroke of sketchStrokes){ctx.beginPath();stroke.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();}};draw();const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*1000/r.width,(e.clientY-r.top)*500/r.height];};canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;activeStroke=[point(e)];sketchStrokes.push(activeStroke);canvas.setPointerCapture(e.pointerId);$('#publish-preview').hidden=true;draw();});canvas.addEventListener('pointermove',e=>{if(activeStroke){activeStroke.push(point(e));draw();}});const finish=()=>{activeStroke=null;};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);canvas.addEventListener('lostpointercapture',finish);$('#undo-sketch').addEventListener('click',()=>{sketchStrokes.pop();draw();$('#publish-preview').hidden=true;announce(tr('Last stroke removed.','Poslednji potez uklonjen.'));});$('#download-sketch').addEventListener('click',()=>{canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='studio-sketch.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);announce(tr('Sketch downloaded.','Skica preuzeta.'));},'image/png');});}
async function loadBoard(){const button=$('#load-board');button.disabled=true;$('#board-status').textContent=tr('Loading public contributions…','Učitavanje javnih priloga…');try{const response=await fetch('https://api.github.com/repos/3esign/inclusive-studio/issues?state=open&per_page=60',{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(12000)});if(!response.ok)throw new Error('HTTP '+response.status);const data=await response.json();if(!Array.isArray(data))throw new Error('Invalid response');const issues=data.filter(i=>!i.pull_request&&i.labels?.some(l=>['idea','submission'].includes(l.name)));$('#board-results').innerHTML=issues.map(i=>{const url=new URL(i.html_url);if(url.origin!=='https://github.com'||!url.pathname.startsWith('/3esign/inclusive-studio/issues/'))return '';const text=String(i.body||'').replace(/!\[[^\]]*\]\([^)]*\)/g,'').replace(/[#*_`>]/g,'').slice(0,230);return `<article class="board-item"><p class="meta">#${Number(i.number)} · ${i.labels.some(l=>l.name==='submission')?tr('Project reference','Referenca projekta'):tr('Idea','Ideja')}</p><h3>${link(url.href,esc(i.title))}</h3><p>${esc(text)}${text.length===230?'…':''}</p><span class="meta">${Number(i.comments)} ${tr('comments','komentara')}</span></article>`;}).join('');$('#board-status').textContent=issues.length?issues.length+' '+tr('public contributions loaded. Showing up to 60 recent open issues.','javnih priloga učitano. Prikaz obuhvata do 60 poslednjih otvorenih objava.'):tr('No open ideas or project references yet.','Još nema otvorenih ideja ni referenci projekata.');}catch{$('#board-status').textContent=tr('The board could not be loaded. Retry or use “View on GitHub” above. Your draft is unaffected.','Tabla nije učitana. Pokušaj ponovo ili koristi „Pogledaj na GitHubu” iznad. Tvoj nacrt je sačuvan odvojeno.');}finally{button.disabled=false;}}
function toggleReading(){document.body.classList.toggle('reading-mode');save('reading',document.body.classList.contains('reading-mode'));updateChrome();announce(tr('View updated.','Prikaz je promenjen.'));}
applyComfort();
$('#language-toggle').addEventListener('click',()=>{setLanguage(lang==='en'?'sr':'en');render();$('#language-toggle').focus();announce(tr('English interface.','Interfejs na srpskom.'));});
$('#reading-toggle').addEventListener('click',toggleReading);
// Read the public, explicitly dated source before rendering timetable-dependent views.
try { const response=await fetch('data/schedule.json',{signal:AbortSignal.timeout(6000)});if(!response.ok)throw new Error('Missing schedule');const data=await response.json();if(validateSchedule(data).length)throw new Error('Invalid schedule');schedule=data;const first=schedule.events.find(e=>e.status==='confirmed');if(first)calendarMonth=new Date(Number(first.start.slice(0,4)),Number(first.start.slice(5,7))-1,1); } catch { scheduleError=true; }
render();

// ---- The course: official data, the teacher's record, links ----
function subject(){
  const p = course.programmes.map(x=>`<tr><td>${esc(tx(x.name))}</td><td><code>${esc(x.code)}</code></td><td>${x.semester}</td><td>${x.ects}</td><td>${esc(tx(x.type))}</td></tr>`).join('');
  const un = course.unconfirmed[lang].map(x=>`<li>${esc(x)}</li>`).join('');
  const out = outcomes.map((o,i)=>`<li><span class="num">${number(i+1)}</span><span>${esc(tx(o))}</span></li>`).join('');
  const eras = about.eras.map(e=>`<article class="era"><div class="era-head"><span class="meta-label">${esc(e.period)}</span><h3>${esc(tx(e.place))}</h3><span class="tag">${tr('Files','Datoteke')}: ${esc(e.files)}</span></div><p>${esc(tx(e.body))}</p></article>`).join('');
  const lk = links.map(g=>`<section class="link-group"><h3>${esc(tx(g.group))}</h3><ul class="link-list">${g.items.map(i=>`<li><a href="${esc(i.url)}">${esc(tx(i.label))} ↗</a></li>`).join('')}</ul></section>`).join('');
  const rules = houseRules.map(r=>`<li>${esc(tx(r))}</li>`).join('');
  return `<div class="page-top"><div><p class="eyebrow">${tr('The course / Official data','Predmet / Zvanični podaci')}</p><h1>${esc(tx(course.title))}</h1><p class="lede">${esc(tx(course.institution))} · ${esc(tx(course.faculty))}<br>${esc(tx(course.teacher))} · ${esc(tx(course.term))}</p></div></div>
  <div class="readable"><h2>${tr('In short','Ukratko')}</h2><p>${tr('An elective architecture course. You take one real, steeply sloping place in Belgrade and design a way to cross it that everyone uses — the same route for everyone. You prove it with measurements, with the Rulebook, and with a check done together with the people it is for.','Izborni predmet na arhitekturi. Uzimaš jedno stvarno, strmo mesto u Beogradu i projektuješ način da se pređe — istom trasom za sve. Dokazuješ merama, Pravilnikom i proverom koju radiš zajedno sa ljudima kojima je projekat namenjen.')}</p></div>
  <blockquote class="thesis"><p>${esc(tx(course.thesis))}</p></blockquote>
  <section class="week-contract notices" aria-labelledby="notices-title"><div><p class="eyebrow">${tr('Notices — all of them','Obaveštenja — sva')}</p><h2 id="notices-title">${tr('Three things, and the rest is material.','Tri stvari, a sve ostalo je gradivo.')}</h2></div>
    <ol class="notice-list">${notices.map((item,i)=>`<li><b>${number(i+1)}</b><div><h3>${esc(tx(item.title))}</h3><p>${esc(tx(item.body))}</p></div></li>`).join('')}</ol></section>
  <section><div class="section-heading"><h2>${tr('Official course data','Zvanični podaci o predmetu')}</h2><span class="tag">${tr('Examination record, 27.08.2026','Zapisnik o polaganju, 27.08.2026')}</span></div>
    <p>${tr('The course runs in two study programmes at once. Both follow the same teaching; the difference in ECTS is settled by the extent of the hand-in, not by different lectures.','Predmet se izvodi u dva studijska programa. Nastava je zajednička, a razlika u ESPB usklađuje se obimom završnog rada, ne različitim predavanjima.')}</p>
    <div class="table-wrap"><table><caption class="sr-only">${tr('Study programmes, codes, semester and ECTS','Studijski programi, šifre, semestar i ESPB')}</caption><thead><tr><th scope="col">${tr('Study programme','Studijski program')}</th><th scope="col">${tr('Code','Šifra')}</th><th scope="col">${tr('Semester','Semestar')}</th><th scope="col">${tr('ECTS','ESPB')}</th><th scope="col">${tr('Type','Tip')}</th></tr></thead><tbody>${p}</tbody></table></div>
    <p class="help">${tr('Grading scale','Skala ocenjivanja')}: ${esc(course.grading)}</p>
    <div class="notice"><p><strong>${tr('Not yet confirmed.','Još nije potvrđeno.')}</strong></p><ul>${un}</ul></div></section>
  <section><div class="section-heading"><h2>${tr('What you should be able to do','Po završetku predmeta student:')}</h2><span class="small muted">${tr('Learning outcomes','Ishodi učenja')}</span></div><ol class="outcome-list">${out}</ol></section>
  <section><div class="section-heading"><h2>${tr('House rules','Pravila rada')}</h2></div><ul class="rule-list">${rules}</ul></section>
  <section id="teacher"><div class="section-heading"><h2>${tr('The teacher','Nastavnik')}</h2><span class="tag">${tr('Counted, not recalled','Prebrojano, ne prepričano')}</span></div>
    <p class="lede">${esc(tx(about.role))}</p><p>${esc(tx(about.lede))}</p>
    <div class="era-list">${eras}</div>
    <p class="help">${esc(tx(about.note))}</p>
    <div class="readable"><h3>${tr('Why the course is taught this way','Zašto se predmet drži ovako')}</h3><p>${esc(tx(about.why))}</p></div></section>
  <section id="links"><div class="section-heading"><h2>${tr('Links','Linkovi')}</h2><span class="small muted">${tr('Checked 01.10.2026','Provereno 01.10.2026')}</span></div><div class="link-grid">${lk}</div></section>`;
}

// ---- Exercises and longer pieces of work ----
function kindLabel(k){return tr({drawing:'Drawing',measurement:'Measurement',reading:'Reading',fieldwork:'Fieldwork',participatory:'With coauthors',digital:'Digital',making:'Making'}[k]||k,{drawing:'Crtež',measurement:'Merenje',reading:'Čitanje',fieldwork:'Teren',participatory:'Sa koautorima',digital:'Digitalno',making:'Izrada'}[k]||k);}
function exerciseCard(e){
  const w = weeks.find(x=>x.n===e.week);
  return `<article class="exercise" id="ex-${esc(e.id)}"><div class="exercise-head"><span class="meta-label">${tr('Week','Nedelja')} ${number(e.week)}</span><span class="tag">${esc(kindLabel(e.kind))}</span></div>
  <h3>${esc(tx(e.title))}</h3><p>${esc(tx(e.task))}</p>
  <dl class="exercise-meta"><dt>${tr('On the weekly A3','Na nedeljnom A3')}</dt><dd>${esc(tx(e.hand))}</dd><dt>${tr('It passes when','Prolazi kada')}</dt><dd>${esc(tx(e.check))}</dd></dl>
  <p class="exercise-links">${e.source.url?`<a href="${esc(e.source.url)}">${esc(e.source.label)} ↗</a>`:`<span class="small muted">${esc(e.source.label)}</span>`}${w?` · <a class="mini-link" href="studio.html?stage=${w.stage}">${tr('Open stage','Otvori fazu')} ${number(w.stage)} ↗</a>`:''}</p></article>`;
}
function work(){
  const byBlock = ['A','B','C'].map(b=>{
    const list = exercises.filter(e=>{const w=weeks.find(x=>x.n===e.week);return w&&w.block===b;});
    if(!list.length) return '';
    return `<section class="exercise-block"><div class="section-heading"><h2>${esc(tx(blocks[b]))}</h2><span class="tag">${list.length} ${tr('exercises','vežbi')}</span></div><div class="exercise-grid">${list.map(exerciseCard).join('')}</div></section>`;
  }).join('');
  const seeds = ideas.map(i=>`<article class="idea"><span class="meta-label">${esc(tx(i.scale))}</span><h3>${esc(tx(i.title))}</h3><p>${esc(tx(i.body))}</p><p class="help"><strong>${tr('Why it is worth doing','Zašto vredi')}:</strong> ${esc(tx(i.why))}</p></article>`).join('');
  return `<div class="page-top"><div><p class="eyebrow">${tr('Exercises / Task → evidence → check','Vežbe / Zadatak → dokaz → provera')}</p><h1>${tr('Work, not topics.','Rad, ne teme.')}</h1><p class="lede">${tr('Every exercise names the week it belongs to, what you hand in, and the test it has to pass. Nothing here can be completed by describing an intention.','Svaka vežba kaže kojoj nedelji pripada, šta A3 list mora da pokaže i koju proveru mora da prođe. Nijedna se ne završava opisom namere.')}</p></div></div>
  <div class="readable"><h2>${tr('In short','Ukratko')}</h2><p>${tr('Below are the exercises of the course, grouped into three blocks. Each week is collected on one A3; if a week has two cards, they are two parts of that same sheet, not two hand-ins. Each card states what its part must show and how it is reviewed. Longer work follows at the bottom.','Ispod su vežbe predmeta, u tri bloka. Svaka nedelja sabira se na jednom A3 listu; ako nedelja ima dve kartice, to su dva dela istog lista, a ne dve predaje. Svaka kartica kaže šta njen deo mora da pokaže i kako se pregleda. Na dnu su predlozi dužeg rada.')}</p></div>
  ${byBlock}
  <section id="seeds"><div class="section-heading"><h2>${tr('Longer work: seminar papers, competitions, research','Duži rad: seminarski, konkursi, istraživanje')}</h2><span class="tag">${ideas.length}</span></div><p>${tr('These are gaps this course can actually fill, not a list of topics. Each one is open; talk to the teacher before starting.','Ovo su praznine koje ovaj predmet stvarno može da popuni, a ne spisak tema. Svaka je otvorena; javi se nastavniku pre početka.')}</p><div class="idea-grid">${seeds}</div></section>`;
}

// ---- The fifteen teaching weeks, shown on the calendar page ----
function weekPlan(){
  const rows = ['A','B','C'].map(b=>{
    const list = weeks.filter(w=>w.block===b);
    return `<tbody><tr class="block-row"><th colspan="4" scope="colgroup">${esc(tx(blocks[b]))}</th></tr>
    ${list.map(w=>`<tr${w.milestone?' class="milestone"':''}><th scope="row">${number(w.n)}</th><td>${esc(tx(w.lecture))}</td><td>${esc(tx(w.studio))}${w.milestone?` <span class="tag">${tr('Milestone','Prekretnica')}</span>`:''}</td><td><a class="mini-link" href="studio.html?stage=${w.stage}">${tr('Stage','Faza')} ${number(w.stage)}</a></td></tr>`).join('')}</tbody>`;
  }).join('');
  return `<section id="weeks"><div class="section-heading"><h2>${tr('The fifteen teaching weeks','Petnaest nastavnih nedelja')}</h2><span class="tag">${tr('Plan, not dates','Plan, ne datumi')}</span></div>
  <p>${tr('This is the sequence of teaching. Confirmed dates are kept in the held-class record; the sequence below does not create additional dates. Each week links to the project stage it serves.','Ovo je redosled nastave. Potvrđeni datumi čuvaju se u evidenciji održanih časova; redosled ispod ne uvodi dodatne datume. Svaka nedelja vodi na fazu projekta kojoj služi.')}</p>
  <div class="table-wrap"><table class="week-table"><caption class="sr-only">${tr('Fifteen teaching weeks: lecture, studio work and the project stage','Petnaest nastavnih nedelja: predavanje, rad u studiju i faza projekta')}</caption><thead><tr><th scope="col">${tr('Wk','Ned.')}</th><th scope="col">${tr('Lecture','Predavanje')}</th><th scope="col">${tr('Studio / project work','Vežbe / rad na projektu')}</th><th scope="col">${tr('Stage','Faza')}</th></tr></thead>${rows}</table></div></section>`;
}

// ---- The real site: measured figures, the problem, the caveat ----
function siteFacts(){
  const f = site.figures.map(x=>`<div class="figure"><dt>${esc(tx(x.label))}</dt><dd>${esc(x.value)}</dd></div>`).join('');
  const th = themes.map(t=>`<article class="theme"><span class="meta-label">${esc(t.key)}</span><h3>${esc(tx(t.title))}</h3><p>${esc(tx(t.body))}</p></article>`).join('');
  const dl = deliverables.map(d=>`<li${d.core?' class="core"':''}><strong>${number(d.n)}.</strong> ${esc(tx(d.text))}${d.core?` <span class="tag">${tr('Compulsory in full','Obavezno u punom obimu')}</span>`:''}</li>`).join('');
  const cr = projectCriteria.map(c=>`<tr><th scope="row">${esc(tx(c.text))}</th><td>${c.share} %</td></tr>`).join('');
  const af = automaticFail[lang].map(x=>`<li>${esc(x)}</li>`).join('');
  const as = assessment.map(a=>`<tr><th scope="row">${esc(tx(a.item))}</th><td>${a.a}</td><td>${a.b}</td></tr>`).join('');
  return `<section id="site"><div class="section-heading"><h2>${tr('The site: Živimo zajedno','Lokacija: Živimo zajedno')}</h2><span class="tag">${tr('Measured 24.11.2025','Mereno 24.11.2025')}</span></div>
  <dl class="figure-grid">${f}</dl>
  <p class="lede">${esc(tx(site.problem))}</p>
  <div class="notice"><p><strong>${tr('What the base is, and what it is not.','Šta podloga jeste, a šta nije.')}</strong> ${esc(tx(site.caveat))}</p></div></section>
  <section id="themes"><div class="section-heading"><h2>${tr('Three themes. A team of two or three takes one.','Tri teme. Tim od dvoje ili troje uzima jednu.')}</h2></div><div class="theme-grid">${th}</div><p class="help">${tr('The theme is registered in week 1 and does not change after the concept review in week 11.','Tema se prijavljuje u 1. nedelji i ne menja se posle koncepta u 11. nedelji.')}</p></section>
  <section id="hand-in"><div class="section-heading"><h2>${tr('What the hand-in must contain','Šta predaja mora da sadrži')}</h2></div><ol class="deliverable-list">${dl}</ol><p class="help">${esc(tx(notRequired))}</p></section>
  <section id="marks"><div class="section-heading"><h2>${tr('How it is marked','Kako se ocenjuje')}</h2></div>
  <div class="table-wrap"><table><caption class="sr-only">${tr('Points by item and programme','Bodovi po stavci i programu')}</caption><thead><tr><th scope="col">${tr('Item','Stavka')}</th><th scope="col">22.OA0068 (5)</th><th scope="col">OAIPUD (4)</th></tr></thead><tbody>${as}</tbody><tfoot><tr><th scope="row">${tr('Total','Ukupno')}</th><td>100</td><td>100</td></tr></tfoot></table></div>
  <h3>${tr('Within the project mark','Unutar ocene projekta')}</h3>
  <div class="table-wrap"><table><caption class="sr-only">${tr('Project criteria and their share','Kriterijumi projekta i njihov udeo')}</caption><thead><tr><th scope="col">${tr('Criterion','Kriterijum')}</th><th scope="col">${tr('Share','Udeo')}</th></tr></thead><tbody>${cr}</tbody></table></div>
  <div class="notice error"><p><strong>${tr('Automatic fail','Automatski pad')}</strong></p><ul>${af}</ul></div></section>`;
}
